from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    best = (0, 0)
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            size = 0
            while q:
                y, x = q.popleft()
                size += 1
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            if size > best[0]:
                best = (size, color)
    color = best[1]
    return [[color] * 3 for _ in range(3)]
